import json
import sys
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone

BASE = "http://localhost:8080"
RANGE_START = datetime(2025, 3, 1, tzinfo=timezone.utc)
RANGE_END = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive: 31 May inclusive
REGIONS = ("north", "south", "east", "west")
MAX_ATTEMPTS = 60

token = None
log = []


def note(msg):
    print(msg, file=sys.stderr, flush=True)


def fetch_token():
    global token
    for attempt in range(MAX_ATTEMPTS):
        try:
            req = urllib.request.Request(BASE + "/token", method="POST", data=b"")
            with urllib.request.urlopen(req, timeout=10) as r:
                token = json.loads(r.read())["token"]
                return token
        except Exception as e:
            note(f"token attempt {attempt}: {e}")
            time.sleep(1)
    raise SystemExit("could not obtain token")


def get(path):
    """GET an authenticated path, retrying on rate limits, auth expiry, and transient errors."""
    if token is None:
        fetch_token()
    for attempt in range(MAX_ATTEMPTS):
        req = urllib.request.Request(BASE + path, headers={"Authorization": f"Bearer {token}"})
        try:
            with urllib.request.urlopen(req, timeout=15) as r:
                body = r.read()
                return json.loads(body)
        except urllib.error.HTTPError as e:
            body = e.read().decode("utf-8", "replace")
            note(f"{path} -> HTTP {e.code} (attempt {attempt}) headers_retry={e.headers.get('Retry-After')} body={body[:300]}")
            log.append({"path": path, "status": e.code, "body": body[:500], "retry_after": e.headers.get("Retry-After")})
            if e.code == 404:
                return None
            if e.code in (401, 403):
                fetch_token()
                continue
            if e.code == 429:
                wait = e.headers.get("Retry-After")
                if wait is None:
                    try:
                        wait = json.loads(body).get("retry_after")
                    except Exception:
                        wait = None
                time.sleep(float(wait) if wait is not None else 5)
                continue
            time.sleep(min(2 ** attempt, 20))
        except Exception as e:
            note(f"{path} -> {type(e).__name__}: {e} (attempt {attempt})")
            log.append({"path": path, "error": str(e)})
            time.sleep(min(2 ** attempt, 20))
    raise SystemExit(f"gave up on {path}")


def fetch_all_listings():
    listings = []
    pages_seen = []
    path = "/orders?page=1"
    total_pages = None
    while path:
        data = get(path)
        if data is None:
            raise SystemExit(f"unexpected 404 on {path}")
        total_pages = data["total_pages"]
        pages_seen.append(data["page"])
        listings.extend(data["items"])
        note(f"page {data['page']}/{total_pages}: {len(data['items'])} items")
        path = data.get("next")
    missing = sorted(set(range(1, total_pages + 1)) - set(pages_seen))
    if missing:
        note(f"pages missing from next-chain: {missing}; fetching directly")
        for p in missing:
            data = get(f"/orders?page={p}")
            pages_seen.append(p)
            listings.extend(data["items"])
    return listings, pages_seen, total_pages


def parse_utc(ts):
    dt = datetime.fromisoformat(ts)
    if dt.tzinfo is None:
        raise ValueError(f"naive timestamp: {ts}")
    return dt.astimezone(timezone.utc)


def main():
    listings, pages_seen, total_pages = fetch_all_listings()
    note(f"listings: {len(listings)}, pages fetched: {len(pages_seen)} of {total_pages}")

    by_id = {}
    duplicates_skipped = 0
    conflicting_dupes = []
    for o in listings:
        oid = o["id"]
        if oid in by_id:
            duplicates_skipped += 1
            if by_id[oid] != o:
                conflicting_dupes.append((by_id[oid], o))
        else:
            by_id[oid] = o
    note(f"distinct orders: {len(by_id)}, duplicate listings discarded: {duplicates_skipped}, conflicting duplicates: {len(conflicting_dupes)}")

    statuses = {}
    for o in by_id.values():
        statuses[o["status"]] = statuses.get(o["status"], 0) + 1
    note(f"status counts: {statuses}")

    qualifying = []
    for o in by_id.values():
        if o["status"] != "shipped":
            continue
        t = parse_utc(o["placed_at"])
        if RANGE_START <= t < RANGE_END:
            qualifying.append(o)
    note(f"qualifying orders: {len(qualifying)}")

    customer_cache = {}
    total = 0
    by_region = {r: 0 for r in REGIONS}
    unknown_customers = []
    for o in qualifying:
        cid = o["customer_id"]
        if cid not in customer_cache:
            customer_cache[cid] = get(f"/customers/{cid}")
        c = customer_cache[cid]
        if c is None:
            unknown_customers.append(o["id"])
            continue
        pct = c["discount_pct"]
        if not isinstance(pct, int):
            raise SystemExit(f"non-integer discount_pct for {cid}: {pct!r}")
        amt = o["amount_cents"]
        if not isinstance(amt, int):
            raise SystemExit(f"non-integer amount for {o['id']}: {amt!r}")
        num = amt * (100 - pct)
        discounted = (num + 50) // 100  # half up, per order, integer arithmetic
        total += discounted
        if c["region"] not in by_region:
            raise SystemExit(f"unexpected region {c['region']!r} for {cid}")
        by_region[c["region"]] += discounted

    note(f"customers fetched: {len(customer_cache)}; unknown customers on qualifying orders: {len(unknown_customers)} {unknown_customers[:10]}")

    result = {
        "total_cents": total,
        "order_count": len(qualifying) - len(unknown_customers),
        "duplicates_skipped": duplicates_skipped,
        "by_region": by_region,
    }
    print(json.dumps(result, indent=2))
    note(f"sum(by_region) == total: {sum(by_region.values()) == total}")
    note(f"conflicting duplicates: {conflicting_dupes[:5]}")
    note(f"errors logged during run: {len(log)}")


if __name__ == "__main__":
    main()

